// The demo GIF's layout: how `scripts/demo-gif.py` turns a run's `--output text`
// into frames.
//
// The GIF itself is regenerated by hand (`just screenshots-gif`) and is not
// hash-gated, because a GIF is not byte-reproducible across Pillow versions —
// and regenerating it needs Pillow and the pinned `oneharness` CLI, neither of
// which `just check` has. So a layout defect would otherwise ship in the next
// regeneration unnoticed. These cases drive the script's own layout functions
// under `python3`, over a stream shaped like the one the fixture graph writes:
// an event whose resolved transcript content runs to many lines, and a
// supervisor instruction longer than the window. Drawing is the one part they
// leave out, and the only part that needs Pillow.

import { spawnSync } from "node:child_process";
import { dirname, join, resolve } from "node:path";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { fileURLToPath } from "node:url";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const SCRIPT = join(REPO_ROOT, "scripts", "demo-gif.py");

/// Load the real script by path (with `-B`, so no `__pycache__` is left in
/// `scripts/`), lay out the stream on stdin, and print the
/// result with the constants it was laid out against.
const DRIVER = `
import importlib.util, json, sys
spec = importlib.util.spec_from_file_location("demo_gif", sys.argv[1])
gif = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gif)
grouped = gif.events(sys.stdin.read().splitlines())
durations = gif.gaps([at for at, _ in grouped])
print(json.dumps({
    "bodies": [body for _, body in grouped],
    "durations": durations,
    "frames": gif.frames([body for _, body in grouped], durations),
    "constants": {name: getattr(gif, name)
                  for name in ("ROWS", "COLS", "LEAD_MS", "MIN_MS", "MAX_MS", "HOLD_MS")},
}))
`;

function layout(lines) {
  const result = spawnSync("python3", ["-I", "-B", "-c", DRIVER, SCRIPT], {
    cwd: REPO_ROOT,
    input: `${lines.join("\n")}\n`,
    encoding: "utf8",
  });
  return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}

/// The supervisor's instruction, as a transcript-referenced `turn-started`
/// renders it: one stamped head and forty lines under it, one over-wide.
const INSTRUCTION = Array.from({ length: 40 }, (_, i) =>
  i === 38 ? `${"wide ".repeat(40)}end` : `instruction line ${i}`,
);

const STREAM = [
  "2026-10-23T02:42:15.716Z graph graph-started node-scope",
  "2026-10-23T02:42:15.719Z worker turn-started turn 1 (assistant) add the retry",
  "2026-10-23T02:42:30.720Z worker member-heartbeat alive",
  "2026-10-23T02:42:33.721Z worker turn-activity tool_result running the gate",
  "2 passed; 0 failed",
  "2026-10-23 nightly run",
  "2026-10-23T02:42:33 local",
  "2026-10-23T02:42:33.737Z worker turn-started turn 1 (user) You are the supervisor.",
  ...INSTRUCTION,
  "2026-10-23T02:42:33.741Z worker turn-completed turn 1 (user) in=10 out=5",
  "2026-10-23T02:42:33.756Z graph graph-settled exit 0",
];

describe("demo-gif layout", () => {
  it("groups each event's resolved content under its stamped line and scrolls a fixed window", () => {
    const run = layout(STREAM);
    assert.equal(run.status, 0, run.stderr);
    const { bodies, durations, frames, constants } = JSON.parse(run.stdout);
    const { ROWS, COLS, LEAD_MS, MIN_MS, MAX_MS, HOLD_MS } = constants;

    // Seven events, not one per line: continuation lines stay with their event.
    assert.equal(bodies.length, 7);
    // Content that opens with a date, even a whole ISO time, is not a stamp.
    assert.deepEqual(bodies[3], STREAM.slice(3, 7));
    assert.equal(bodies[4].length, 1 + INSTRUCTION.length);

    // Pace comes from the stamps between events, clamped at both ends.
    assert.deepEqual(durations, [MIN_MS, MAX_MS, MAX_MS, MIN_MS, MIN_MS, MIN_MS, HOLD_MS]);

    // The empty window, then one frame per event, none taller than the window.
    assert.equal(frames.length, bodies.length + 1);
    assert.deepEqual(frames[0], [[], LEAD_MS]);
    for (const [rows] of frames) {
      assert.ok(rows.length <= ROWS, `${rows.length} rows`);
      for (const row of rows) assert.ok(row.length <= COLS, row);
    }

    // The tool's whole output lands in the frame of its event.
    assert.deepEqual(frames[4][0].slice(-4), STREAM.slice(3, 7));

    // The instruction is longer than the window, so its frame has scrolled past
    // its own head and ends on its last line; the over-wide line is folded at
    // the window's width with a hanging indent.
    const [instructionFrame] = frames[5];
    assert.equal(instructionFrame.length, ROWS);
    assert.ok(!instructionFrame.includes(STREAM[7]));
    const wide = INSTRUCTION[38];
    assert.deepEqual(instructionFrame.slice(-4), [
      INSTRUCTION[37],
      wide.slice(0, COLS),
      `  ${wide.slice(COLS)}`,
      INSTRUCTION[39],
    ]);

    // The settled stream is the last frame, held before the loop.
    assert.equal(frames.at(-1)[0].at(-1), STREAM.at(-1));
    assert.equal(frames.at(-1)[1], HOLD_MS);
  });

  it("refuses a stream that opens without a stamp, naming what to check", () => {
    const run = layout(["2 passed; 0 failed", ...STREAM]);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /the stream opens without a stamp: '2 passed; 0 failed'/);
    assert.match(run.stderr, /--output text/);
    assert.equal(run.stdout, "");
  });
});
